// German C1 practice rooms: 6 modules x 12 rooms x 3 questions.
window.deRooms = window.deRooms || {};
deRooms.C1 = [
  // Module 1: Nuance & Subtle Meaning
  [
    {t:"Shades of meaning",s:"Vocabulary",qs:[{q:"What does 'vermeintlich' mean?",opts:["supposed","obvious","deliberate","forgotten"],a:0,ex:"'vermeintlich' marks something believed to be true that probably isn't: der vermeintliche Täter."},{q:"'Es sei dahingestellt, ob ...' means:",opts:["It is certain that ...","It is forbidden to ...","It was decided that ...","Whether ... remains open"],a:3,ex:"The fixed Konjunktiv I phrase leaves a question deliberately unresolved."},{q:"'gewissermaßen' is closest to:",opts:["without exception","by coincidence","to a certain extent","at the latest"],a:2,ex:"'gewissermaßen' qualifies a statement, like 'sozusagen': Er hat gewissermaßen recht."}]},
    {t:"Near-synonyms",s:"Vocabulary",qs:[{q:"Which word says something only looks true but is in fact false?",opts:["anscheinend","offenbar","scheinbar","offensichtlich"],a:2,ex:"In careful usage 'scheinbar' = only seemingly; 'anscheinend' and 'offenbar' = apparently, probably true."},{q:"'unterschwellig' means:",opts:["explicit and openly stated","subliminal, below the surface","overwhelming and sudden","temporary and fleeting"],a:1,ex:"'die Schwelle' is the threshold; 'unterschwellig' is what works beneath conscious awareness."},{q:"Fill the gap: 'Ich habe ___ geschlafen – höchstens zwei Stunden.'",opts:["kaum","durchaus","eben","sozusagen"],a:0,ex:"'kaum' means hardly, which matches 'at most two hours'; 'durchaus' would mean quite/certainly."}]},
    {t:"Stress in nuance words",s:"Pronunciation",qs:[{q:"Listen. Which syllable of 'gewissermaßen' is stressed?",opts:["-wis-","ge-","-ma-","-ßen"],a:0,ex:"The prefix ge- is unstressed; the stress falls on the stem 'wiss': ge-WIS-ser-ma-ßen.",say:"gewissermaßen"},{q:"Listen. How is 'doch' spoken in this friendly invitation?",opts:["strongly stressed","with a long rising tone","drawn out and loud","short and unstressed"],a:3,ex:"As a modal particle 'doch' is unstressed; a stressed DOCH would contradict something.",say:"Komm doch mal vorbei!"},{q:"Listen. Where is the stress in 'durchaus'?",opts:["on durch-","on both equally","on -aus","on the u of durch"],a:2,ex:"'durchaus' is stressed on its second syllable: durch-AUS, unlike most words beginning with durch-.",say:"Das ist durchaus möglich."}]},
    {t:"Modal particles",s:"Grammar",qs:[{q:"Shared knowledge: 'Du weißt ___, dass ich keine Zeit habe.'",opts:["mal","etwa","ja","bloß"],a:2,ex:"'ja' signals that the speaker assumes the listener already knows the fact."},{q:"Which particle makes the invitation warm and urging? 'Komm ___ mal vorbei!'",opts:["eben","doch","etwa","ja"],a:1,ex:"'doch mal' in an imperative softens it into a friendly encouragement; stressed 'ja' would sound like a warning."},{q:"Resigned acceptance: 'Das ist ___ so, da kann man nichts machen.'",opts:["halt","doch","etwa","mal"],a:0,ex:"'halt' (like 'eben') presents a fact as unchangeable: that's just how it is."}]},
    {t:"Particle position & emphasis",s:"Grammar",qs:[{q:"Which sentence places the modal particle correctly?",opts:["Das ist ja interessant.","Das ja ist interessant.","Das ist interessant ja.","Ja ist das interessant."],a:0,ex:"Modal particles stand in the middle field after the finite verb, never in position 1 or at the end."},{q:"'Er ist DOCH gekommen' (doch stressed) means:",opts:["He obviously came, as you know","He came only briefly","He hardly came at all","He came after all, against expectation"],a:3,ex:"Stressed 'doch' contradicts an earlier assumption: contrary to what was expected, he came."},{q:"Choose the correct order: unstressed pronoun and particles.",opts:["Könnten Sie vielleicht mal mir helfen?","Könnten mal Sie mir vielleicht helfen?","Könnten Sie mir vielleicht mal helfen?","Mal könnten Sie mir vielleicht helfen?"],a:2,ex:"Unstressed pronouns come early in the middle field, before particles like 'vielleicht mal'."}]},
    {t:"Reading: a polite refusal",s:"Reading",qs:[{q:"Read: 'Ich würde dir ja gern helfen, aber heute habe ich eben keine Zeit. Vielleicht klappt es ja nächste Woche.' What does the writer mean?",opts:["They refuse to help ever again","They will help today after all","They'd like to help but simply can't today","They already helped this week"],a:2,ex:"'ja gern' shows goodwill, 'eben' presents lack of time as a simple fact, and next week is offered."},{q:"Read: 'Die Ergebnisse sind gewissermaßen überraschend. Es sei dahingestellt, ob sie sich wiederholen lassen.' What is true?",opts:["The author is sure they can be repeated","The author leaves open whether they can be repeated","The results were fully expected","The author rejects the results"],a:1,ex:"'Es sei dahingestellt, ob' leaves the question open; 'gewissermaßen' only softens 'surprising'."},{q:"Read: 'Der vermeintliche Experte hatte kaum Ahnung vom Thema.' What does the sentence say?",opts:["The so-called expert knew hardly anything","The real expert knew a lot","The expert had no time for the topic","The expert barely missed the topic"],a:0,ex:"'vermeintlich' casts doubt on the expert title, and 'kaum Ahnung' means hardly any idea."}]},
    {t:"Listening: tone and certainty",s:"Listening",qs:[{q:"Listen. How does the speaker react?",opts:["with surprised interest","with open anger","with a clear refusal","with obvious boredom"],a:0,ex:"Here 'ja' expresses surprise: the speaker finds something unexpectedly interesting.",say:"Das ist ja interessant!"},{q:"Listen. How sure is the speaker?",opts:["completely certain, having seen it","sure that it is not true","has no idea at all","fairly sure, judging by signs"],a:3,ex:"'anscheinend' means apparently: the speaker infers it from evidence but did not witness it.",say:"Er ist anscheinend schon nach Hause gegangen."},{q:"Listen. What does the speaker say about the plan?",opts:["It is hardly possible","It is certainly impossible","It is quite possible","It was possible before"],a:2,ex:"'durchaus' strengthens 'möglich': quite or entirely possible.",say:"Der Plan ist durchaus realistisch und möglich."}]},
    {t:"Diplomatic replies",s:"Speaking",qs:[{q:"A colleague asks you to take on extra work. Which is the most diplomatic refusal?",opts:["Nein, das mache ich auf gar keinen Fall, tut mir leid.","Das ist nicht mein Problem, frag bitte jemand anderen.","Ich würde ja gern, aber diese Woche ist es kaum machbar.","Mach das doch bitte einfach selbst, ich habe keine Lust."],a:2,ex:"'ja gern' signals goodwill and 'kaum machbar' softens the refusal without a blunt 'no'."},{q:"You want to soften 'Das ist falsch.' in a meeting. What do you say?",opts:["Das ist total und absolut falsch.","Das ist meines Erachtens nicht ganz zutreffend.","Das ist eben einfach falsch, sorry.","Das ist doch völlig daneben."],a:1,ex:"'meines Erachtens' and 'nicht ganz' hedge the criticism, which is expected in diplomatic talk."},{q:"Someone says 'Das klappt bestimmt.' You doubt it but stay polite. You say:",opts:["Es sei dahingestellt, ob das wirklich klappt.","Das klappt durchaus ganz sicher bestimmt.","Das klappt eben bestimmt, wie immer.","Das klappt vermeintlich ganz bestimmt."],a:0,ex:"The phrase leaves the outcome open without contradicting the speaker directly."}]},
    {t:"Writing precise wording",s:"Writing",qs:[{q:"Choose the correctly written sentence.",opts:["Das ist durchaus möglich.","Das ist durch aus möglich.","Das ist durchaus möglig.","Das is durchaus möglich."],a:0,ex:"'durchaus' is one word, and 'möglich' ends in -lich."},{q:"Fill the gap in the email: 'Die ___ Lösung hat sich als Irrtum erwiesen.'",opts:["vermeintlich","vermeintlichen","vermeintlicher","vermeintliche"],a:3,ex:"After the definite article in the feminine nominative singular, the adjective takes the weak ending -e."},{q:"Which sentence emphasises 'diesen Fehler' by putting it in position 1?",opts:["Er hat diesen Fehler nie zugegeben.","Er hat nie diesen Fehler zugegeben.","Diesen Fehler hat er nie zugegeben.","Hat er diesen Fehler nie zugegeben?"],a:2,ex:"Moving an object into position 1 (the Vorfeld) highlights it; the verb stays in position 2."}]},
    {t:"Particles & politeness",s:"Culture",qs:[{q:"Why do German speakers often add 'mal' to requests like 'Kannst du mal kommen?'",opts:["It turns the request into a strict order","It means the action must happen only once","It makes the request sound casual and less demanding","It is required in formal business letters"],a:2,ex:"'mal' (from 'einmal') downplays a request, so it sounds lighter and friendlier."},{q:"In which context should you use 'halt' and 'eben' sparingly?",opts:["chatting with friends","a formal written report","a casual phone call","talking to family"],a:1,ex:"Modal particles, especially 'halt', are typical of informal speech and are kept rare in formal writing."},{q:"Where is the particle 'halt' traditionally most common?",opts:["in southern Germany, Austria and Switzerland","only in northern Germany and Berlin","only in written legal and official texts","only in East Frisia and on the coast"],a:0,ex:"'halt' is the southern counterpart of northern 'eben', though it is now heard everywhere."}]},
    {t:"Review: nuance",s:"Review",qs:[{q:"Which word fits? 'Das Problem ist ___ lösbar, aber es kostet Zeit.'",opts:["durchaus","kaum","vermeintlich","scheinbar"],a:0,ex:"'durchaus lösbar' = quite solvable; 'aber es kostet Zeit' adds a limitation, which fits only a positive claim."},{q:"'sozusagen' is used to ...",opts:["introduce a strict, technical definition","mark the start of a direct quotation","express a sequence of events in time","signal an approximate or figurative expression"],a:3,ex:"'sozusagen' (so to speak) flags that a word is used loosely or metaphorically."},{q:"Which sentence highlights 'gestern' by putting it first?",opts:["Sie hat gestern endlich angerufen.","Sie hat endlich gestern angerufen.","Gestern hat sie endlich angerufen.","Hat sie gestern endlich angerufen?"],a:2,ex:"Position 1 gives prominence; when 'gestern' takes it, the subject moves after the verb."}]},
    {t:"Challenge: fine distinctions",s:"Challenge",qs:[{q:"'Er ist scheinbar reich.' – in careful usage this implies:",opts:["He is probably rich, judging by signs","He is definitely and obviously rich","He looks rich but isn't really","He used to be rich but lost it all"],a:2,ex:"Strictly, 'scheinbar' means only seemingly; 'anscheinend reich' would mean probably rich."},{q:"'Bist du ___ schon fertig?' – the speaker is surprised and suspects it's not true.",opts:["eben","etwa","halt","ja"],a:1,ex:"In yes/no questions 'etwa' expresses surprise or disbelief: Surely you're not done already?"},{q:"Which sentence uses 'eben' as a modal particle?",opts:["Er ist eben so, daran ändert sich nichts.","Er ist eben erst angekommen.","Die Straße hier ist ganz eben.","Eben hat jemand für dich angerufen."],a:0,ex:"Only the first means 'that's just how he is'; the others mean 'just now' or 'flat'."}]}
  ],
  // Module 2: Academic Reading & Precision
  [
    {t:"Academic key words",s:"Vocabulary",qs:[{q:"'die Untersuchung' means:",opts:["the study / investigation","the lecture / talk","the footnote / citation","the conclusion / result"],a:0,ex:"'untersuchen' = to examine; 'die Untersuchung' is a study or examination."},{q:"'die vorliegende Arbeit' refers to:",opts:["a previous paper by the author","an unfinished first draft","a thesis that was rejected","the present paper (this one)"],a:3,ex:"'vorliegen' = to be at hand, so 'vorliegend' means the text the reader is holding now."},{q:"'daraus folgt' means:",opts:["in contrast","for example","it follows that","despite this"],a:2,ex:"'daraus' (from that) + 'folgt' (follows) introduces a logical conclusion."}]},
    {t:"Thesis, sources, citation",s:"Vocabulary",qs:[{q:"The opposing position to a 'These' is the:",opts:["Synthese","Hypothese","Antithese","Prothese"],a:2,ex:"The 'Antithese' opposes the thesis; the 'Synthese' combines both; a 'Prothese' is a prosthesis."},{q:"'die oben genannten Punkte' means:",opts:["the main points below","the above-mentioned points","the points named in the title","the points to be named later"],a:1,ex:"'oben' (above) + 'genannt' (named) refers back to something already mentioned."},{q:"What is a 'Fußnote'?",opts:["a note at the foot of the page","the summary at the start","the table of contents","the list of figures"],a:0,ex:"'Fuß' (foot) + 'Note': footnotes hold sources and comments at the bottom of a page."}]},
    {t:"Academic word stress",s:"Pronunciation",qs:[{q:"Listen. Which syllable of 'Untersuchung' is stressed?",opts:["-su-","Un-","-ter-","-chung"],a:0,ex:"'untersuchen' is inseparable, so the stress falls on the stem: un-ter-SU-chung.",say:"die Untersuchung"},{q:"Listen. Which part of 'vorliegende' is stressed?",opts:["-lie-","-gen-","-de","vor-"],a:3,ex:"'vorliegen' is a separable verb, and separable prefixes carry the stress: VOR-lie-gen-de.",say:"die vorliegende Studie"},{q:"Listen. What sound does 'tz' in 'trotz' make?",opts:["z, as in 'zoo'","th, as in 'think'","ts, as in 'cats'","s, as in 'sun'"],a:2,ex:"German 'tz' and 'z' are both pronounced ts.",say:"trotz des Regens"}]},
    {t:"Genitive prepositions",s:"Grammar",qs:[{q:"'___ der Ergebnisse ziehen wir folgende Schlüsse.' (based on the results)",opts:["Trotz","Innerhalb","Aufgrund","Anstatt"],a:2,ex:"'aufgrund' + genitive gives a cause or basis: on the basis of the results."},{q:"'Trotz ___ Kritik blieb das Modell bestehen.'",opts:["die","der","den","dem"],a:1,ex:"'trotz' takes the genitive in standard German; feminine genitive singular is 'der'."},{q:"'Die Daten werden innerhalb ___ Woche ausgewertet.'",opts:["einer","eine","einem","einen"],a:0,ex:"'innerhalb' + genitive; the feminine indefinite article in the genitive is 'einer'."}]},
    {t:"Konjunktiv I & participles",s:"Grammar",qs:[{q:"Which form is the Konjunktiv I used in academic reporting? 'Er behauptet, er ___ Experte.'",opts:["sei","ist","wäre","war"],a:0,ex:"Konjunktiv I of 'sein' is 'sei'; it reports a claim without the writer endorsing it."},{q:"Unpack the attribute: 'die im Jahr 2020 durchgeführte Untersuchung' =",opts:["die Untersuchung, die 2020 durchführte","die Untersuchung, die 2020 durchführen wird","die Untersuchung, die 2020 durchgeführt hat","die Untersuchung, die 2020 durchgeführt wurde"],a:3,ex:"Partizip II as an attribute is passive: the study was carried out (wurde durchgeführt)."},{q:"Choose the correct extended attribute.",opts:["die seit Jahren steigende Kosten","die steigenden seit Jahren Kosten","die seit Jahren steigenden Kosten","die seit Jahren gestiegen Kosten"],a:2,ex:"Extra details come before the participle, which takes the ending -en after 'die' in the plural."}]},
    {t:"Reading: an abstract",s:"Reading",qs:[{q:"Read: 'Die vorliegende Untersuchung analysiert den Einfluss sozialer Medien auf das Leseverhalten Jugendlicher. Aufgrund der geringen Stichprobe sind die Ergebnisse nur eingeschränkt übertragbar.' What limits the results?",opts:["the lack of footnotes","the age of the researchers","the small sample","the authors' media use"],a:2,ex:"'aufgrund der geringen Stichprobe' gives the reason: the sample was small."},{q:"Read: 'Trotz zahlreicher Einwände hält der Autor an seiner These fest. Daraus folgt, dass die Debatte noch offen ist.' What is true?",opts:["The author drops his thesis after the objections","The author keeps his thesis despite objections","There were no objections to the thesis at all","The debate about the thesis is now closed"],a:1,ex:"'festhalten an' = to stick to; 'trotz zahlreicher Einwände' = despite many objections."},{q:"Read: 'Müller (2019) behauptet, das Modell sei veraltet.' What does 'sei' tell you?",opts:["The writer reports Müller's claim without endorsing it","The writer strongly agrees with Müller's view","The model is definitely outdated, as a fact","Müller is being quoted in the future tense"],a:0,ex:"Konjunktiv I marks indirect speech: the claim belongs to Müller, not to the writer."}]},
    {t:"Listening: a lecture excerpt",s:"Listening",qs:[{q:"Listen. What happened to the number of students?",opts:["It doubled within ten years","It halved within ten years","It stayed the same for ten years","It doubled in the last year"],a:0,ex:"'innerhalb der letzten zehn Jahre' = within the last ten years; 'verdoppelt' = doubled.",say:"Innerhalb der letzten zehn Jahre hat sich die Zahl der Studierenden verdoppelt."},{q:"Listen. When was the data anonymised?",opts:["before the experiment","after publication","despite the experiment","during the experiment"],a:3,ex:"'während' + genitive means during: während des Experiments.",say:"Während des Experiments wurden alle Daten anonymisiert."},{q:"Listen. What does the author stress about the results?",opts:["They are final","They are wrong","They are provisional","They are confidential"],a:2,ex:"'vorläufig' means provisional; 'seien' reports her statement in Konjunktiv I.",say:"Die Autorin betont, die Ergebnisse seien vorläufig."}]},
    {t:"Presenting findings",s:"Speaking",qs:[{q:"You present a study in a seminar. Which opening sounds academic?",opts:["Also, ich erzähl euch jetzt mal was über ...","Hey Leute, heute geht's um so ein Thema ...","Im Mittelpunkt meines Referats steht die Frage, ...","Ja, keine Ahnung, aber mein Thema ist ..."],a:2,ex:"'Im Mittelpunkt steht' is a standard academic frame for naming the central question."},{q:"How do you neutrally report what a researcher claims?",opts:["Schmidt behauptet, die Methode ist klar super.","Schmidt behauptet, die Methode sei zuverlässig.","Schmidt hat total recht mit seiner Methode.","Die Methode ist zuverlässig, und Punkt."],a:1,ex:"Konjunktiv I ('sei') reports the claim while keeping your own distance from it."},{q:"A listener points out a weakness. Which reply is suitable?",opts:["Ein berechtigter Einwand – die Stichprobe war tatsächlich klein.","Das ist doch völlig egal für die Ergebnisse meiner Arbeit.","Das steht doch irgendwo in der Arbeit, lesen Sie nach.","Keine Ahnung, da müssen Sie wohl den Autor fragen."],a:0,ex:"Acknowledging a valid objection ('berechtigter Einwand') is expected academic politeness."}]},
    {t:"Writing an abstract",s:"Writing",qs:[{q:"Which sentence is grammatically correct?",opts:["Aufgrund des hohen Aufwands wurde die Studie verkürzt.","Aufgrund dem hohen Aufwand wurde die Studie verkürzt.","Aufgrund des hohen Aufwand wurde die Studie verkürzt.","Aufgrund der hohe Aufwand wurde die Studie verkürzt."],a:0,ex:"'aufgrund' takes the genitive: masculine 'des hohen Aufwands' with -s on the noun."},{q:"Fill the gap: 'Die ___ Thesen werden im Folgenden diskutiert.'",opts:["oben genannte","oben genannter","oben nennenden","oben genannten"],a:3,ex:"After 'die' in the plural the attribute takes the weak ending -en; it is passive, so 'genannt'."},{q:"Choose the correct word order.",opts:["Im Folgenden die Methode wird genauer beschrieben.","Im Folgenden wird genauer beschrieben die Methode.","Im Folgenden wird die Methode genauer beschrieben.","Die Methode im Folgenden wird genauer beschrieben."],a:2,ex:"'Im Folgenden' fills position 1, so the finite verb 'wird' must come second."}]},
    {t:"Academic conventions",s:"Culture",qs:[{q:"What is generally avoided in German academic writing?",opts:["the passive voice and impersonal forms","footnotes and citations","informal 'du' and colloquial phrases","genitive and participle constructions"],a:2,ex:"Academic German is impersonal and formal; the passive, footnotes and genitives are all common."},{q:"What is a 'Doktormutter' or 'Doktorvater'?",opts:["the parent of a medical doctor","the supervisor of a doctoral thesis","the head of a hospital","the university president"],a:1,ex:"German calls the PhD supervisor 'Doktorvater/-mutter', reflecting a close mentoring role."},{q:"How do you address a female professor in a formal email?",opts:["Sehr geehrte Frau Professorin Weber,","Hallo Prof. Weber, na, wie geht's?","Liebe Weber, hier kurz meine Frage,","Hey Frau Weber, kurze Frage,"],a:0,ex:"Formal emails to academics use 'Sehr geehrte' plus the title and surname."}]},
    {t:"Review: academic German",s:"Review",qs:[{q:"Which preposition takes the genitive?",opts:["innerhalb","mit","gegen","seit"],a:0,ex:"'innerhalb' takes the genitive; 'mit' and 'seit' take the dative, 'gegen' the accusative."},{q:"Which verb makes 'Die Untersuchung zeigt, dass ...' more academic?",opts:["macht","tut","kriegt","belegt"],a:3,ex:"'belegen' (to prove, document) is a precise academic verb; the others are vague or colloquial."},{q:"Choose the Konjunktiv I form of 'können' for 'er'.",opts:["kann","könnte","könne","konnte"],a:2,ex:"Konjunktiv I takes the infinitive stem + -e: er könne. 'könnte' is Konjunktiv II."}]},
    {t:"Challenge: precise structures",s:"Challenge",qs:[{q:"Which form clearly marks indirect speech? 'Die Autoren behaupten, sie ___ neue Daten.'",opts:["haben","habe","hätten","hatten"],a:2,ex:"Konjunktiv I 'sie haben' looks like the indicative, so Konjunktiv II 'hätten' is used instead."},{q:"Turn into an extended attribute: 'die Theorie, die von vielen Forschern kritisiert wird'",opts:["die von vielen Forschern kritisierende Theorie","die von vielen Forschern kritisierte Theorie","die kritisierte von vielen Forschern Theorie","die von vielen Forschern kritisiert Theorie"],a:1,ex:"A passive relative clause becomes Partizip II with an ending; the agent goes before it."},{q:"Which sentence is correct in written standard German?",opts:["Während des Vortrags herrschte völlige Stille.","Während des Vortrag herrschte völlige Stille.","Während der Vortrags herrschte völlige Stille.","Während den Vortrag herrschte völlige Stille."],a:0,ex:"'während' + genitive: masculine 'des Vortrags' needs both 'des' and the -s ending."}]}
  ],
  // Module 3: Idioms & Stylistic Choice
  [
    {t:"Idioms: luck and blindness",s:"Vocabulary",qs:[{q:"'Schwein haben' means:",opts:["to be lucky","to be greedy","to be untidy","to be lazy"],a:0,ex:"Despite the pig, 'Schwein haben' is positive: to have unexpected good luck."},{q:"'Tomaten auf den Augen haben' means:",opts:["to be crying after bad news","to be red-faced with embarrassment","to be very hungry and impatient","to fail to notice something obvious"],a:3,ex:"With tomatoes over your eyes you can't see what is right in front of you."},{q:"'auf dem Holzweg sein' means:",opts:["to be on holiday in the woods","to make good progress","to be on the wrong track","to work very hard"],a:2,ex:"A 'Holzweg' was a logging path that led into the forest, not to a destination."}]},
    {t:"More idioms",s:"Vocabulary",qs:[{q:"'die Kirche im Dorf lassen' means:",opts:["to stay at home","to keep a secret","to keep things in proportion","to respect old traditions"],a:2,ex:"The idiom warns against exaggerating: leave the church where it belongs."},{q:"'Ich verstehe nur Bahnhof' means:",opts:["I only care about trains","I don't understand a thing","I understand the main point","I want to leave right now"],a:1,ex:"Colloquially, 'nur Bahnhof verstehen' means understanding nothing at all."},{q:"'Das ist nicht mein Bier' means:",opts:["That's not my concern","I don't drink alcohol","That's not my fault","I don't like that"],a:0,ex:"The idiom distances you from a matter that is someone else's business."}]},
    {t:"Sounds in idioms",s:"Pronunciation",qs:[{q:"Listen. How are the two h's in 'Kuhhaut' pronounced?",opts:["only the h of 'Haut' is heard","both h's are clearly heard","neither h is heard","only the h of 'Kuh' is heard"],a:0,ex:"The h in 'Kuh' only lengthens the vowel; the h starting 'Haut' is breathed.",say:"Das geht auf keine Kuhhaut."},{q:"Listen. How does 'Schw' at the start of 'Schwein' sound?",opts:["s + English w","sk + v","ch as in 'Bach' + w","sh + v"],a:3,ex:"German 'sch' is 'sh', and German 'w' is pronounced like English 'v'.",say:"Da hast du aber Schwein gehabt."},{q:"Listen. Which sound ends the word 'Holzweg'?",opts:["g as in 'go'","ch as in 'ich'","k","no sound"],a:2,ex:"Final devoicing: b, d, g at the end of a word sound like p, t, k.",say:"Du bist auf dem Holzweg."}]},
    {t:"Emphasis: the Vorfeld",s:"Grammar",qs:[{q:"What is the 'Vorfeld' in a German main clause?",opts:["the end of the sentence","the subordinate clause","the position before the finite verb","the position after the subject"],a:2,ex:"The Vorfeld is position 1, before the finite verb; whatever stands there is highlighted."},{q:"Which element is highlighted in 'Mit diesem Ergebnis hatte niemand gerechnet'?",opts:["niemand (the subject)","mit diesem Ergebnis","gerechnet (the participle)","hatte (the finite verb)"],a:1,ex:"The phrase moved into the Vorfeld gets emphasis; the subject 'niemand' follows the verb."},{q:"Which sentence uses hypotaxis (subordination)?",opts:["Weil es regnete, blieben wir zu Hause.","Es regnete. Wir blieben zu Hause.","Es regnete, wir blieben zu Hause.","Es regnete und wir blieben zu Hause."],a:0,ex:"Hypotaxis uses a subordinate clause ('weil ...', verb last); the others link main clauses."}]},
    {t:"Fixed idioms, exact form",s:"Grammar",qs:[{q:"Which version of the idiom is correct?",opts:["Er hat Tomaten auf den Augen.","Er hat Tomaten in den Augen.","Er hat eine Tomate auf dem Auge.","Er hat Tomaten vor den Augen."],a:0,ex:"Idioms are fixed: the preposition, number and case cannot be changed."},{q:"Complete: 'Du gehst mir auf ___ Keks.'",opts:["dem","das","die","den"],a:3,ex:"'auf' + accusative expresses direction here; 'der Keks' becomes 'den Keks'."},{q:"Complete: 'Wir sollten die Kirche im ___ lassen.'",opts:["Haus","Stadt","Dorf","Garten"],a:2,ex:"The fixed form is 'die Kirche im Dorf lassen'; swapping the noun breaks the idiom."}]},
    {t:"Reading: idioms in messages",s:"Reading",qs:[{q:"Read: 'Ehrlich gesagt verstehe ich bei der neuen Software nur Bahnhof. Kannst du mir kurz helfen?' What is the problem?",opts:["The writer has to go to the station","The writer finds the software too easy","The writer doesn't understand the software","The writer wants to buy software"],a:2,ex:"'nur Bahnhof verstehen' means not understanding anything, hence the request for help."},{q:"Read: 'Mit dem Wetter hatten wir echt Schwein – drei Tage Sonne!' How was the weather?",opts:["unpleasantly hot","luckily sunny","rainy, as feared","constantly changing"],a:1,ex:"'Schwein haben' means being lucky: three days of sunshine."},{q:"Read: 'Wer glaubt, dass sich das Problem von selbst löst, ist auf dem Holzweg.' What does the author think?",opts:["The problem will not solve itself","The problem will solve itself","The problem is about forestry","Nobody believes the problem exists"],a:0,ex:"Anyone believing the opposite is 'auf dem Holzweg', i.e. mistaken."}]},
    {t:"Listening: idioms in use",s:"Listening",qs:[{q:"Listen. What does the speaker want the other person to do?",opts:["stop exaggerating","go to church","stay in the village","make things worse"],a:0,ex:"'die Kirche im Dorf lassen' asks someone to keep things in proportion.",say:"Jetzt lass mal die Kirche im Dorf, so schlimm ist es nicht."},{q:"Listen. How does the speaker feel about the noise?",opts:["amused","indifferent","relaxed","annoyed"],a:3,ex:"'jemandem auf den Keks gehen' means to get on someone's nerves.",say:"Der Lärm von nebenan geht mir total auf den Keks."},{q:"Listen. What does the speaker think of the boss's behaviour?",opts:["It is perfectly fair","It is rather funny","It is outrageous","It is slightly odd"],a:2,ex:"'Das geht auf keine Kuhhaut' says something is beyond all acceptable limits.",say:"Wie der Chef mit uns umgeht, das geht auf keine Kuhhaut."}]},
    {t:"Using idioms in context",s:"Speaking",qs:[{q:"A friend wants you to settle a dispute between strangers. You say it's none of your business:",opts:["Das ist nicht mein Wein.","Das ist nicht mein Brot.","Das ist nicht mein Bier.","Das ist nicht mein Kaffee."],a:2,ex:"Only 'Bier' forms the idiom; the other drinks and foods have no idiomatic meaning here."},{q:"Your friend misses a sign right in front of him. You joke:",opts:["Hast du heute Schwein gehabt?","Hast du Tomaten auf den Augen?","Bist du im Dorf geblieben?","Verstehst du nur Bahnhof?"],a:1,ex:"'Tomaten auf den Augen haben' is about not seeing the obvious."},{q:"In a job interview you want to say you were lucky. What is most appropriate?",opts:["Da hatte ich großes Glück.","Da hatte ich echt Schwein.","Da hatte ich voll Dusel.","Da hatte ich Megaschwein."],a:0,ex:"'Schwein haben' and 'Dusel' are colloquial; a job interview calls for the neutral 'Glück'."}]},
    {t:"Style and register",s:"Writing",qs:[{q:"Which sentence is written in a neutral, formal style?",opts:["Das Projekt ist leider gescheitert.","Das Projekt ist voll in die Hose gegangen.","Das Projekt ist total den Bach runtergegangen.","Das Projekt ging echt mega schief."],a:0,ex:"'scheitern' is the neutral word; the other versions use colloquial idioms and intensifiers."},{q:"Choose the correctly spelled idiom.",opts:["Ich verstehe nur Banhof.","Ich verstehe nur Bahnhoff.","Ich verstehe nur Bahnhöf.","Ich verstehe nur Bahnhof."],a:3,ex:"'Bahnhof' = 'Bahn' (railway) + 'Hof' (yard), with one f and no umlaut."},{q:"Join as main clauses (parataxis): 'Es war spät. Wir gingen nach Hause.'",opts:["Es war spät, also wir gingen nach Hause.","Es war spät, weil gingen wir nach Hause.","Es war spät, also gingen wir nach Hause.","Es war spät, deshalb wir gingen nach Hause."],a:2,ex:"'also' and 'deshalb' are adverbs that fill position 1, so the verb must follow directly."}]},
    {t:"Idioms and culture",s:"Culture",qs:[{q:"Around New Year, which small gift is a classic German lucky charm?",opts:["a chocolate rabbit","a wooden nutcracker","a marzipan pig","a paper lantern"],a:2,ex:"Pigs symbolise luck, as in 'Schwein haben', so marzipan pigs are given at Silvester."},{q:"'Der Dativ ist dem Genitiv sein Tod' is a well-known book about:",opts:["a famous crime case in Berlin","German usage and common language mistakes","medieval German history and law","regional German cooking traditions"],a:1,ex:"Bastian Sick's columns and books humorously discuss correct and incorrect German usage."},{q:"Where is 'Du gehst mir auf den Keks' appropriate?",opts:["among friends or family","in a formal complaint letter","in an academic paper","in a speech to shareholders"],a:0,ex:"The idiom is colloquial, so it belongs in informal, personal conversations."}]},
    {t:"Review: idioms & style",s:"Review",qs:[{q:"Which idiom fits? 'Mit dieser Annahme bist du leider ___.'",opts:["auf dem Holzweg","im Dorf","auf dem Keks","im Bahnhof"],a:0,ex:"'auf dem Holzweg sein' means being mistaken, which matches a wrong assumption."},{q:"'die Hervorhebung' means:",opts:["the summary","the footnote","the rhythm","emphasis"],a:3,ex:"'hervorheben' = to highlight; the noun is emphasis, e.g. through the Vorfeld."},{q:"Parataxis means:",opts:["a chain of subordinate clauses","a fixed idiomatic phrase","a sequence of main clauses","a passive construction"],a:2,ex:"Parataxis places clauses side by side as equals; hypotaxis subordinates them."}]},
    {t:"Challenge: style choices",s:"Challenge",qs:[{q:"Which version is the most literary and hypotactic?",opts:["Der Regen hörte auf. Sie verließ das Haus. Nebel lag schwer über dem Tal.","Der Regen hörte auf, sie verließ das Haus, und Nebel lag über dem Tal.","Als sie, nachdem der Regen aufgehört hatte, das Haus verließ, lag Nebel im Tal.","Der Regen war vorbei, sie ging aus dem Haus, im Tal lag dichter Nebel."],a:2,ex:"It nests one subordinate clause inside another, while the others line up main clauses."},{q:"Which sentence uses an idiom in the wrong register?",opts:["Na, du hast ja wieder mal Schwein gehabt!","Sehr geehrter Herr Lang, Sie gehen mir auf den Keks.","Mensch, lass doch die Kirche im Dorf!","Ich versteh nur Bahnhof, erklär's nochmal."],a:1,ex:"A colloquial idiom clashes with the formal salutation 'Sehr geehrter'; the others are casual."},{q:"'Das geht auf keine Kuhhaut' means:",opts:["That's beyond all limits","That is very cheap","That's not my concern","That's a lucky coincidence"],a:0,ex:"Even a whole cowhide (old writing material) couldn't list it all: it is outrageous."}]}
  ],
  // Module 4: Long-form Listening & Summary
  [
    {t:"Lecture words",s:"Vocabulary",qs:[{q:"'der Vortrag' means:",opts:["the lecture / talk","the contract","the advantage","the forecast"],a:0,ex:"Don't confuse 'Vortrag' (talk) with 'Vertrag' (contract) or 'Vorteil' (advantage)."},{q:"'die Kernaussage' is:",opts:["the final question","a side remark","the introduction","the key statement"],a:3,ex:"'der Kern' = core; the Kernaussage is the central message of a text or talk."},{q:"'Stichpunkte notieren' means:",opts:["to write a full essay","to copy the slides","to take bullet notes","to record the audio"],a:2,ex:"'Stichpunkte' are brief keyword notes, not full sentences."}]},
    {t:"Structure markers",s:"Vocabulary",qs:[{q:"'im Wesentlichen' means:",opts:["in detail","at the beginning","essentially","by accident"],a:2,ex:"'das Wesentliche' is the essential part; 'im Wesentlichen' reduces a point to its core."},{q:"Which marker introduces a consequence?",opts:["einerseits","folglich","abschließend","zunächst"],a:1,ex:"'folglich' = consequently; 'einerseits' opens a contrast, 'abschließend' a conclusion."},{q:"'Einerseits ...' is usually answered later by:",opts:["andererseits","folglich","zunächst","schließlich"],a:0,ex:"'einerseits ... andererseits' (on the one hand ... on the other) frames two sides."}]},
    {t:"Stress in long words",s:"Pronunciation",qs:[{q:"Listen. Which syllable of 'zusammenfassend' carries the main stress?",opts:["-sam-","zu-","-fas-","-send"],a:0,ex:"The prefix 'zusammen' is stressed on 'sam', and separable prefixes carry the main stress.",say:"zusammenfassend"},{q:"Listen. Where is the main stress in the compound 'Kernaussage'?",opts:["-aus-","-sa-","-ge","Kern-"],a:3,ex:"In German compounds the first element usually carries the main stress.",say:"die Kernaussage"},{q:"Listen. What sound does 'ß' make in 'abschließend'?",opts:["a voiced, buzzing z","a b sound, as in Bus","a sharp, voiceless s","a sh sound, as in Schule"],a:2,ex:"'ß' is always a voiceless s; it follows long vowels and diphthongs like 'ie'.",say:"abschließend"}]},
    {t:"Plusquamperfekt",s:"Grammar",qs:[{q:"'Nachdem er ___, stellte man Fragen.'",opts:["gesprochen hat","sprach","gesprochen hatte","spricht"],a:2,ex:"With a main clause in the Präteritum, 'nachdem' takes the Plusquamperfekt for the earlier event."},{q:"How is the Plusquamperfekt formed?",opts:["habe/bin + past participle","hatte/war + past participle","würde + infinitive","werde + infinitive"],a:1,ex:"It uses the past of 'haben' or 'sein' plus Partizip II: er hatte gesagt, sie war gegangen."},{q:"'Nachdem der Vortrag ___, gab es eine Diskussion.'",opts:["geendet hatte","geendet war","geendet hat","endet"],a:0,ex:"'enden' forms its perfect with 'haben', and the earlier event needs the past form 'hatte'."}]},
    {t:"Tense sequence & markers",s:"Grammar",qs:[{q:"'Nachdem wir angekommen ___, begann der Vortrag.'",opts:["waren","hatten","sind","haben"],a:0,ex:"'ankommen' is a verb of motion with 'sein', and the earlier past event needs 'waren'."},{q:"Which sentence has the correct tense sequence?",opts:["Nachdem sie die Notizen gelesen hat, schrieb sie die Zusammenfassung.","Nachdem sie die Notizen las, hatte sie die Zusammenfassung geschrieben.","Nachdem sie die Notizen gelesen hatte, schreibt sie die Zusammenfassung.","Nachdem sie die Notizen gelesen hatte, schrieb sie die Zusammenfassung."],a:3,ex:"Plusquamperfekt in the 'nachdem' clause pairs with Präteritum in the main clause."},{q:"Choose the correct word order after 'folglich'.",opts:["Folglich sich ergibt ein neues Bild.","Folglich ein neues Bild ergibt sich.","Folglich ergibt sich ein neues Bild.","Folglich, ein neues Bild ergibt sich."],a:2,ex:"'folglich' is an adverb in position 1, so the finite verb follows immediately."}]},
    {t:"Reading: lecture notes",s:"Reading",qs:[{q:"Read: 'Im Wesentlichen vertritt die Referentin die These, dass Homeoffice die Produktivität steigert. Andererseits räumt sie ein, dass die Kommunikation leidet.' What does she concede?",opts:["Productivity falls","Home office should end","Communication suffers","Nothing at all"],a:2,ex:"'einräumen' = to concede; she admits that communication suffers."},{q:"Read: 'Nachdem die Firma ihre Strategie geändert hatte, stiegen die Umsätze.' What happened first?",opts:["Sales rose","The strategy changed","Both happened at once","The firm closed"],a:1,ex:"The Plusquamperfekt ('geändert hatte') marks the earlier of the two past events."},{q:"Read: 'Der Autor argumentiert, dass Städte grüner werden müssen. Zusammenfassend lässt sich sagen, dass er vor allem auf Parks setzt.' What kind of summary is this?",opts:["neutral, reporting without evaluation","personal, giving the writer's opinion","informal, written in slang","a direct, word-for-word quotation"],a:0,ex:"'Der Autor argumentiert, dass' attributes the ideas to the author and adds no judgement."}]},
    {t:"Listening: following a talk",s:"Listening",qs:[{q:"Listen. Which two points does the speaker contrast?",opts:["rising costs and better quality","falling costs and worse quality","rising costs and worse quality","falling costs and better quality"],a:0,ex:"'gestiegen' = risen, 'verbessert' = improved; 'einerseits ... andererseits' contrasts them.",say:"Einerseits sind die Kosten gestiegen, andererseits hat sich die Qualität verbessert."},{q:"Listen. Which part of the talk is this?",opts:["the beginning","a digression","the question round","the end"],a:3,ex:"'abschließend' (finally, in conclusion) signals the closing part of a talk.",say:"Abschließend möchte ich noch einmal die drei wichtigsten Punkte zusammenfassen."},{q:"Listen. What started after the study had been published?",opts:["a new study","a long silence","a heated debate","a lawsuit"],a:2,ex:"'eine heftige Debatte' = a heated debate; it followed the earlier event in the Plusquamperfekt.",say:"Nachdem die Studie veröffentlicht worden war, begann eine heftige Debatte."}]},
    {t:"Summarising aloud",s:"Speaking",qs:[{q:"You have to summarise a podcast in one sentence. How do you start?",opts:["Also, ich fand den Podcast echt total mega ...","Der Podcast war irgendwie so, na ja, ...","Im Wesentlichen geht es in dem Podcast um ...","Keine Ahnung, worum es da genau ging, ..."],a:2,ex:"'Im Wesentlichen geht es um' leads straight to the core content, as a summary should."},{q:"After a talk, you want to question a claim critically. You say:",opts:["Die Zahlen sind halt einfach so, wie sie sind.","Man sollte die Zahlen allerdings kritisch hinterfragen.","Ich glaube diesen Zahlen grundsätzlich alles.","Zahlen interessieren mich eigentlich nicht."],a:1,ex:"'kritisch hinterfragen' politely challenges the data without dismissing the speaker."},{q:"During a lecture you missed a point. What is a polite question?",opts:["Könnten Sie den letzten Punkt bitte noch einmal erläutern?","Wie bitte? Sagen Sie das gefälligst noch einmal!","Hä, was haben Sie da gerade eben gesagt?","Das war jetzt viel zu schnell, nochmal bitte!"],a:0,ex:"Konjunktiv II 'Könnten Sie' plus 'bitte' makes a polite request; 'gefälligst' sounds rude."}]},
    {t:"Writing a critical summary",s:"Writing",qs:[{q:"Which sentence suits a neutral summary?",opts:["Die Autorin vertritt die Auffassung, dass ...","Ich finde total, dass die Autorin ...","Die Autorin hat leider völlig unrecht, ...","Super spannend fand ich, dass ..."],a:0,ex:"'die Auffassung vertreten' reports the author's view; the others add personal evaluation."},{q:"Fill the gap: '___ lässt sich sagen, dass die These überzeugt.'",opts:["Zusammenfassung","Zusammenfassen","Zusammenfassende","Zusammenfassend"],a:3,ex:"The participle used as an adverb, 'zusammenfassend', fits the fixed phrase."},{q:"Which sentence is punctuated and ordered correctly?",opts:["Nachdem der Redner geendet hatte gab es Applaus.","Nachdem der Redner geendet hatte, es gab Applaus.","Nachdem der Redner geendet hatte, gab es Applaus.","Nachdem der Redner hatte geendet, gab es Applaus."],a:2,ex:"A comma closes the subordinate clause, whose verb comes last; the main clause starts with its verb."}]},
    {t:"Lectures in German culture",s:"Culture",qs:[{q:"How do students in Germany traditionally show appreciation at the end of a lecture?",opts:["by standing up in silence","by whistling loudly","by knocking on the desks","by snapping their fingers"],a:2,ex:"Knocking on the desk with the knuckles is the traditional German academic applause."},{q:"What does 'c.t.' (das akademische Viertel) after a lecture time mean?",opts:["It lasts exactly a quarter of an hour","It starts 15 minutes after the stated time","A quarter of the students must attend","It takes place in the university quarter"],a:1,ex:"'cum tempore' means the lecture begins a quarter of an hour later; 's.t.' means sharp."},{q:"What is the 'roter Faden' of a talk?",opts:["the main thread that holds it together","a warning signal for errors","the list of sources","a red ribbon for the speaker"],a:0,ex:"The 'red thread' is the line of argument that connects all parts of a talk."}]},
    {t:"Review: listening & summary",s:"Review",qs:[{q:"Which word signals the final point?",opts:["abschließend","einerseits","zunächst","folglich"],a:0,ex:"'abschließend' = finally; 'zunächst' opens, 'einerseits' contrasts, 'folglich' concludes logically."},{q:"'kritisch hinterfragen' means:",opts:["to praise warmly","to repeat word for word","to ask for help","to question critically"],a:3,ex:"'hinterfragen' means to look behind a claim and examine its basis."},{q:"'Nachdem ich die Folge ___, schrieb ich Notizen.'",opts:["gehört habe","hörte","gehört hatte","gehört war"],a:2,ex:"'hören' takes 'haben'; the earlier action before 'schrieb' needs the Plusquamperfekt."}]},
    {t:"Challenge: report vs evaluate",s:"Challenge",qs:[{q:"Which summary sentence evaluates rather than reports?",opts:["Der Autor stellt drei Thesen zur Diskussion.","Die Autorin geht zunächst auf die Ursachen ein.","Der Autor übertreibt maßlos und ignoriert Fakten.","Der Referent fasst abschließend die Ergebnisse zusammen."],a:2,ex:"'übertreibt maßlos' is the summariser's own judgement; the others describe what the author does."},{q:"Choose: 'Nachdem er ins Ausland ___, ___ er seine Familie nur selten.'",opts:["gezogen hatte / sah","gezogen war / sah","gezogen ist / sah","zog / hatte gesehen"],a:1,ex:"'ziehen' (to move) takes 'sein'; the earlier event is Plusquamperfekt, the later one Präteritum."},{q:"A speaker says 'Folglich ...'. What should your notes mark next?",opts:["a consequence of the previous point","a new topic, unrelated to the last","a counterargument to the thesis","a personal anecdote of the speaker"],a:0,ex:"'folglich' links a conclusion to what came before, so mark it as a result."}]}
  ],
  // Module 5: Formal Writing, Speaking & Editing
  [
    {t:"Formal letter words",s:"Vocabulary",qs:[{q:"'umgehend' means:",opts:["immediately","roundabout","eventually","rarely"],a:0,ex:"In formal letters 'umgehend' = without delay; it is not related to 'Umweg' (detour)."},{q:"'die Stellungnahme' means:",opts:["the job position / post","the parking space / bay","the posture / stance","the statement / response"],a:3,ex:"'Stellung nehmen' = to take a position on something, so the noun is a formal statement."},{q:"'Bezug nehmend auf Ihr Schreiben' means:",opts:["despite your letter","instead of your letter","with reference to your letter","before your letter"],a:2,ex:"'Bezug nehmen auf' = to refer to; it opens formal replies."}]},
    {t:"Requests & attachments",s:"Vocabulary",qs:[{q:"'anbei' in an email means:",opts:["nearby / close","by the way / incidentally","attached / enclosed","in advance / beforehand"],a:2,ex:"'anbei' announces an attachment: Anbei sende ich Ihnen die Unterlagen."},{q:"'überarbeiten' means:",opts:["to translate","to revise","to deliver","to sign"],a:1,ex:"'einen Text überarbeiten' means to rework and improve it."},{q:"Which phrase introduces a polite formal request?",opts:["Ich möchte Sie bitten, ...","Ich verlange sofort, ...","Sie müssen jetzt, ...","Machen Sie gefälligst ..."],a:0,ex:"'Ich möchte Sie bitten' is polite and formal; the others sound like demands."}]},
    {t:"Formal sounds",s:"Pronunciation",qs:[{q:"Listen. How is 'ch' pronounced in 'Hochachtungsvoll'?",opts:["like ch in 'Bach'","like ch in 'ich'","like k","like sh"],a:0,ex:"After a, o, u and au, 'ch' is the back 'Bach' sound.",say:"Hochachtungsvoll"},{q:"Listen. How is 'ee' pronounced in 'geehrte'?",opts:["as one long e: gehrte","like 'ay' in 'say'","like 'ee' in 'see'","as two vowels: ge-ehrte"],a:3,ex:"'ge-' is a separate syllable with a short schwa, then a new syllable starts with a long e.",say:"Sehr geehrte Damen und Herren"},{q:"Listen. Which syllable of 'umgehend' is stressed?",opts:["-ge-","-hend","um-","-ge- and -hend equally"],a:2,ex:"Like the separable verb 'umgehen', 'umgehend' is stressed on its first syllable.",say:"Bitte antworten Sie umgehend."}]},
    {t:"The formal letter frame",s:"Grammar",qs:[{q:"Which salutation is correct when you don't know the recipient?",opts:["Sehr geehrter Damen und Herren,","Sehr geehrten Damen und Herren,","Sehr geehrte Damen und Herren,","Sehr geehrtes Damen und Herren,"],a:2,ex:"The plural nominative without an article takes the ending -e: geehrte Damen und Herren."},{q:"Fill: 'Sehr ___ Frau Dr. Weber,'",opts:["geehrter","geehrte","geehrten","geehrtes"],a:1,ex:"Feminine nominative without an article: geehrte Frau; for a man it is 'geehrter Herr'."},{q:"Fill: 'Bezug ___ auf Ihr Schreiben vom 5. Mai ...'",opts:["nehmend","genommen","nehmen","nimmt"],a:0,ex:"The fixed formula uses the present participle: Bezug nehmend auf (also 'bezugnehmend')."}]},
    {t:"Editing: fillers & clutter",s:"Grammar",qs:[{q:"Best edited version of 'Ich wollte eigentlich irgendwie fragen, ob ...':",opts:["Ich möchte fragen, ob ...","Ich wollte irgendwie fragen, ob ...","Ich wollte eigentlich mal fragen, ob ...","Eigentlich wollte ich irgendwie fragen, ob ..."],a:0,ex:"Fillers like 'eigentlich' and 'irgendwie' add nothing in formal text and are cut."},{q:"'Anbei ___ ich Ihnen die Unterlagen.'",opts:["senden","gesendet","zu senden","sende"],a:3,ex:"'Anbei' fills position 1, so the finite verb 'sende' comes second, before the subject."},{q:"Remove the bloated nominal phrase: 'Wir führen eine Überprüfung der Daten durch.'",opts:["Wir führen die Daten durch.","Wir überprüfen eine Durchführung.","Wir überprüfen die Daten.","Wir prüfen über die Daten."],a:2,ex:"'eine Überprüfung durchführen' is wordy; the simple verb 'überprüfen' says the same."}]},
    {t:"Reading: formal letters",s:"Reading",qs:[{q:"Read: 'Bezug nehmend auf meine Bestellung vom 3. März muss ich Ihnen mitteilen, dass die Ware beschädigt ankam. Ich möchte Sie bitten, umgehend Ersatz zu schicken.' What does the writer want?",opts:["a full refund by next month","to cancel the whole order","a replacement sent immediately","to order more of the goods"],a:2,ex:"'Ersatz' = replacement and 'umgehend' = immediately."},{q:"Read: 'Anbei finden Sie meine Stellungnahme zu den Vorwürfen.' What is attached?",opts:["a copy of the accusations themselves","the writer's response to the accusations","an invoice for the writer's services","a job application with a CV"],a:1,ex:"'Stellungnahme' is the writer's statement; 'Vorwürfe' are the accusations it responds to."},{q:"Read: 'Für Rückfragen stehe ich Ihnen gern zur Verfügung. Hochachtungsvoll, Dr. M. Kurz' What does the closing suggest?",opts:["a very formal, rather distant letter","a casual note to a close friend","an angry, insulting outburst","a cheerful thank-you card"],a:0,ex:"'Hochachtungsvoll' is the most formal closing, today often felt as distant."}]},
    {t:"Listening: spontaneous speech",s:"Listening",qs:[{q:"Listen. How many points does the speaker name?",opts:["three","two","four","five"],a:0,ex:"'Grob gesagt' introduces a rough overview: Kosten, Zeit und Qualität are three points.",say:"Grob gesagt geht es um drei Punkte: Kosten, Zeit und Qualität."},{q:"Listen. What does the speaker suggest?",opts:["cancelling the project","speeding up the project","starting a new project","postponing the project"],a:3,ex:"'verschieben' = to postpone; 'Spontan würde ich sagen' marks an unprepared opinion.",say:"Spontan würde ich sagen, dass wir das Projekt verschieben sollten."},{q:"Listen. What is the deadline?",opts:["from Friday on","Monday at the latest","Friday at the latest","before Thursday"],a:2,ex:"'bis spätestens Freitag' = by Friday at the latest.",say:"Wir bitten Sie, die Unterlagen bis spätestens Freitag einzureichen."}]},
    {t:"Speaking off the cuff",s:"Speaking",qs:[{q:"You get an unexpected question in a meeting. How do you buy time politely?",opts:["Keine Ahnung, das ist mir auch egal.","Dazu sage ich jetzt lieber gar nichts.","Gute Frage – spontan würde ich sagen, ...","Das ist eine ziemlich dumme Frage."],a:2,ex:"Acknowledging the question and using 'spontan würde ich sagen' gives you time to think."},{q:"You want to give a rough approximation in a talk. Which hedge is correct?",opts:["Grob gefragt","Grob gesagt","Groß gesagt","Grob sagen"],a:1,ex:"'grob gesagt' (roughly speaking) is the fixed hedge, like 'kurz gesagt'."},{q:"At an official hearing you must give your formal response. You say:",opts:["Ich möchte dazu wie folgt Stellung nehmen.","Ich will da jetzt mal was dazu sagen.","Also, dazu sag ich mal Folgendes, ne.","Hört mal alle her, jetzt rede ich."],a:0,ex:"'Stellung nehmen' and 'wie folgt' are the formal way to announce a statement."}]},
    {t:"Writing: a formal complaint",s:"Writing",qs:[{q:"Choose the correctly written closing.",opts:["Mit freundlichen Grüßen","Mit freundliche Grüßen","Mit freundlichen Gruß","Mit freundlichem Grüßen"],a:0,ex:"'mit' takes the dative plural: freundlichen Grüßen."},{q:"Fill the gap: 'Ich möchte Sie bitten, mir den Betrag umgehend ___.'",opts:["erstatten","zu erstattet","erstattet zu","zu erstatten"],a:3,ex:"'bitten' is followed by an infinitive clause with 'zu' + infinitive at the end."},{q:"Choose the correct sentence announcing an attachment.",opts:["Beigefügt Sie erhalten die Rechnung.","Beigefügt erhalten die Rechnung Sie.","Beigefügt erhalten Sie die Rechnung.","Sie beigefügt erhalten die Rechnung."],a:2,ex:"'Beigefügt' is in position 1, the verb second, then the pronoun subject 'Sie'."}]},
    {t:"Formal correspondence",s:"Culture",qs:[{q:"What usually follows 'Sehr geehrte Damen und Herren' in a modern German letter?",opts:["a full stop, then a new paragraph","a comma, then 'Hallo'","a comma, then text starting in lower case","a colon, then text in capitals"],a:2,ex:"Today the salutation ends with a comma and the text continues in lower case unless it starts with a noun."},{q:"Which closing is very formal and rather rare today?",opts:["Mit freundlichen Grüßen","Hochachtungsvoll","Viele Grüße","Liebe Grüße"],a:1,ex:"'Hochachtungsvoll' is old-fashioned and distant; 'Mit freundlichen Grüßen' is the standard."},{q:"When is 'Liebe Grüße' a suitable email closing?",opts:["with friends or close colleagues","in a complaint to an authority","in a job application","in a letter to a court"],a:0,ex:"'Liebe Grüße' is warm and informal, so it fits only personal relationships."}]},
    {t:"Review: formal German",s:"Review",qs:[{q:"'umgehend' is a formal synonym of:",opts:["sofort","später","selten","langsam"],a:0,ex:"Both mean immediately; 'umgehend' is typical of business and official letters."},{q:"Which word is a filler that should be cut from a formal text?",opts:["folglich","aufgrund","anbei","irgendwie"],a:3,ex:"'irgendwie' (somehow) is vague; the others carry logical or formal meaning."},{q:"Which sentence fits an email with a CV attached?",opts:["Nebenbei sende ich Ihnen meinen Lebenslauf.","Vorbei sende ich Ihnen meinen Lebenslauf.","Anbei sende ich Ihnen meinen Lebenslauf.","Beiseite sende ich Ihnen meinen Lebenslauf."],a:2,ex:"Only 'anbei' means enclosed; 'nebenbei' means by the way."}]},
    {t:"Challenge: editing a letter",s:"Challenge",qs:[{q:"Find the error: 'Sehr geehrte Herr Müller, Bezug nehmend auf Ihr Schreiben ...'",opts:["'Herr' should be 'Herrn'","'Ihr' should be 'ihr'","'geehrte' should be 'geehrter'","'Bezug' should be lower case"],a:2,ex:"For a man the adjective needs -er: Sehr geehrter Herr; 'Herrn' belongs in the address field."},{q:"Best edit of 'Wir möchten Ihnen hiermit die Mitteilung machen, dass der Termin verschoben wird.'",opts:["Wir machen Ihnen hiermit Mitteilung über den Termin.","Wir teilen Ihnen mit, dass der Termin verschoben wird.","Wir möchten mitteilen machen, dass der Termin verschoben wird.","Hiermit Mitteilung: Termin wird verschoben gemacht."],a:1,ex:"The verb 'mitteilen' replaces the clumsy noun phrase 'die Mitteilung machen'."},{q:"Which opening mixes registers inappropriately?",opts:["Sehr geehrte Damen und Herren, ich bin echt sauer, Leute!","Sehr geehrte Damen und Herren, ich bin sehr verärgert.","Hallo Tom, ich bin echt sauer auf dich!","Lieber Tom, ich bin ziemlich verärgert."],a:0,ex:"A formal salutation followed by slang ('echt sauer, Leute') breaks the register."}]}
  ],
  // Module 6: Nominal Style & Professional Communication
  [
    {t:"Nouns for business",s:"Vocabulary",qs:[{q:"The noun formed from 'entscheiden' is:",opts:["die Entscheidung","die Entscheidheit","die Entschiedung","die Entscheidnis"],a:0,ex:"Many verbs form feminine nouns with -ung: entscheiden -> die Entscheidung."},{q:"'die Tagesordnung' means:",opts:["the daily newspaper","the train timetable","the daily routine","the agenda"],a:3,ex:"The Tagesordnung lists the points of a meeting; a daily routine is 'der Tagesablauf'."},{q:"'die Rückmeldung' means:",opts:["the return ticket","the resignation","the feedback / reply","the reminder"],a:2,ex:"'sich zurückmelden' = to get back to someone; 'Rückmeldung' is a reply or feedback."}]},
    {t:"Funktionsverbgefüge",s:"Vocabulary",qs:[{q:"'in Betracht ziehen' means:",opts:["to move house","to watch the stars","to consider","to reject"],a:2,ex:"'der Betracht' (consideration) + 'ziehen' forms a set phrase meaning to consider."},{q:"Which verb completes 'eine Entscheidung ___'?",opts:["stellen","treffen","nehmen","ziehen"],a:1,ex:"The fixed pairing is 'eine Entscheidung treffen'; the noun carries the meaning, the verb is weak."},{q:"'in Kraft treten' means:",opts:["to come into force","to step down","to gain strength","to enter a building"],a:0,ex:"Laws and rules 'treten in Kraft' when they become valid."}]},
    {t:"Stress in business nouns",s:"Pronunciation",qs:[{q:"Listen. Which syllable of 'Umsetzung' is stressed?",opts:["Um-","-set-","-zung","-set- and -zung equally"],a:0,ex:"'umsetzen' is separable, so its prefix keeps the stress in the noun: UM-set-zung.",say:"die Umsetzung"},{q:"Listen. How is 'ü' pronounced in 'Verfügung'?",opts:["like English 'oo' in 'moon'","like English 'you'","like German 'i' in 'Igel'","a long ü with rounded lips"],a:3,ex:"For ü, say 'i' with your tongue and round your lips as for 'u'; here it is long.",say:"zur Verfügung stellen"},{q:"Listen. Where is the main stress in 'Tagesordnung'?",opts:["-ges-","-ord-","Ta-","-nung"],a:2,ex:"The first part of a compound normally carries the main stress: TA-ges-ord-nung.",say:"die Tagesordnung"}]},
    {t:"Nominalisation",s:"Grammar",qs:[{q:"Turn into a noun phrase: 'weil die Kosten steigen'",opts:["wegen die steigenden Kosten","wegen der steigende Kosten","wegen der steigenden Kosten","wegen den steigend Kosten"],a:2,ex:"'wegen' + genitive plural 'der'; the participle 'steigend' takes the weak ending -en."},{q:"The noun formed from the adjective 'wichtig' is:",opts:["die Wichtigheit","die Wichtigkeit","die Wichtigung","die Wichtigschaft"],a:1,ex:"Adjectives ending in -ig form nouns with -keit: wichtig -> die Wichtigkeit."},{q:"Infinitives used as nouns take which article? '___ Verhandeln dauert lange.'",opts:["Das","Der","Die","Den"],a:0,ex:"Nominalised infinitives are always neuter and capitalised: das Verhandeln."}]},
    {t:"Clauses to prepositions",s:"Grammar",qs:[{q:"'Nachdem das Projekt abgeschlossen war, ...' becomes:",opts:["Nach Abschluss des Projekts, ...","Nach Abschluss dem Projekt, ...","Nachdem Abschluss des Projekts, ...","Nach Abschließen das Projekt, ..."],a:0,ex:"'nachdem' (conjunction) becomes 'nach' (preposition) + noun + genitive attribute."},{q:"'Wenn Sie zustimmen, ...' becomes:",opts:["Mit Ihrer Zustimmen ...","Bei Ihre Zustimmung ...","Für Ihrer Zustimmung ...","Bei Ihrer Zustimmung ..."],a:3,ex:"A conditional 'wenn' clause often becomes 'bei' + dative noun: bei Ihrer Zustimmung."},{q:"'Obwohl es Bedenken gab, ...' becomes:",opts:["Trotz die Bedenken ...","Wegen der Bedenken ...","Trotz der Bedenken ...","Statt der Bedenken ..."],a:2,ex:"Concessive 'obwohl' becomes 'trotz' + genitive; 'wegen' would give a cause instead."}]},
    {t:"Reading: business messages",s:"Reading",qs:[{q:"Read: 'Nach eingehender Prüfung ziehen wir Ihr Angebot in Betracht. Wir bitten um Ihre Rückmeldung bis zum 15. Mai.' What is the company doing?",opts:["rejecting the offer","accepting the offer","considering the offer","ignoring the offer"],a:2,ex:"'in Betracht ziehen' = to consider, so no final decision has been made yet."},{q:"Read: 'Die neue Regelung tritt am 1. Januar in Kraft. Die Unterlagen werden Ihnen rechtzeitig zur Verfügung gestellt.' What happens on 1 January?",opts:["The documents are sent","The new rule takes effect","The rule is discussed","The office closes"],a:1,ex:"'in Kraft treten' = to come into force; the documents just arrive 'in good time'."},{q:"Read: 'Tagesordnung: 1. Begrüßung 2. Budgetplanung 3. Verschiedenes' Which item is second?",opts:["budget planning","the welcome","any other business","the minutes"],a:0,ex:"'Budgetplanung' = budget planning; 'Begrüßung' is the welcome, 'Verschiedenes' any other business."}]},
    {t:"Listening: a meeting",s:"Listening",qs:[{q:"Listen. What is the speaker doing?",opts:["opening the meeting","closing the meeting","postponing the meeting","leaving the meeting"],a:0,ex:"'die Sitzung eröffnen' = to open the meeting; 'begrüßen' = to welcome.",say:"Ich eröffne die Sitzung und begrüße Sie alle herzlich."},{q:"Listen. What was decided?",opts:["to raise the budget","to keep the budget","to review the budget later","to cut the budget"],a:3,ex:"'eine Entscheidung treffen' = to decide; 'kürzen' = to cut.",say:"Wir haben die Entscheidung getroffen, das Budget zu kürzen."},{q:"Listen. What does the speaker ask for?",opts:["a meeting at the end of the week","a payment by the end of the week","a reply by the end of the week","a report early next week"],a:2,ex:"'um Rückmeldung bitten' = to ask for a reply; 'bis Ende der Woche' sets the deadline.",say:"Wir bitten um Ihre Rückmeldung bis Ende der Woche."}]},
    {t:"Chairing a meeting",s:"Speaking",qs:[{q:"You want to take the floor in a meeting. You say:",opts:["Jetzt bin ich mal dran mit Reden ...","Ruhe bitte, jetzt spreche ich hier ...","Wenn ich dazu kurz etwas sagen dürfte ...","Hört mal zu, ich hab da was ..."],a:2,ex:"Konjunktiv II 'dürfte' makes the request to speak polite and formal."},{q:"As chair you summarise the decisions. Which sentence fits?",opts:["Also, irgendwie haben wir heute was beschlossen.","Ich fasse zusammen: Wir haben drei Beschlüsse gefasst.","Was haben wir eigentlich heute so gemacht?","Okay, das war's dann für heute, tschüss."],a:1,ex:"'Ich fasse zusammen' and 'Beschlüsse fassen' are the formal phrases for summarising decisions."},{q:"A client asks for the documents. You reply formally:",opts:["Gern stellen wir Ihnen die Unterlagen zur Verfügung.","Gern stellen wir Ihnen die Unterlagen in Verfügung.","Gern stellen wir Ihnen die Unterlagen zu Verfügung.","Gern stellen wir Ihnen die Unterlagen zur Verfügungen."],a:0,ex:"The fixed expression is 'zur Verfügung stellen': 'zur' (zu der) and singular 'Verfügung'."}]},
    {t:"Writing: a professional email",s:"Writing",qs:[{q:"Which preposition is correct after 'bitten'? Choose the sentence.",opts:["Wir bitten um Rückmeldung bis Freitag.","Wir bitten für Rückmeldung bis Freitag.","Wir bitten nach Rückmeldung bis Freitag.","Wir bitten auf Rückmeldung bis Freitag."],a:0,ex:"'bitten' takes the preposition 'um': um etwas bitten = to ask for something."},{q:"Fill the gap: 'Das Gesetz ist am 1. Mai in Kraft ___.'",opts:["getretet","getreten worden","tritt","getreten"],a:3,ex:"'treten' is irregular (getreten) and takes 'sein' here, since it describes a change of state."},{q:"Rewrite in nominal style: 'Wir prüfen den Vertrag sorgfältig.'",opts:["Die sorgfältige Prüfung dem Vertrag erfolgt durch uns.","Die sorgfältig Prüfung des Vertrags erfolgt durch uns.","Die sorgfältige Prüfung des Vertrags erfolgt durch uns.","Die sorgfältige Prüfung des Vertrag erfolgt durch uns."],a:2,ex:"The adverb becomes an adjective with an ending, and the object becomes a genitive: des Vertrags."}]},
    {t:"Business culture",s:"Culture",qs:[{q:"In a first business email to a new German client, which address is usual?",opts:["'du' and the first name","'du' and the surname","'Sie' and the surname","'ihr' and the first name"],a:2,ex:"German business contacts start with 'Sie' + Herr/Frau + surname until 'du' is offered."},{q:"What is 'Verschiedenes' on a German agenda?",opts:["the minutes of the last meeting","any other business","the budget for the year","the welcome and introductions"],a:1,ex:"'Verschiedenes' (miscellaneous) is the last agenda item for remaining topics."},{q:"Why shouldn't you overdo the Nominalstil in emails?",opts:["Too many nouns make a text heavy and hard to read","Nouns are considered rude in business","It is grammatically incorrect German","It is only used in Austria"],a:0,ex:"Nominal style sounds formal, but piled-up nouns slow the reader down; balance is key."}]},
    {t:"Review: nominal style",s:"Review",qs:[{q:"'zur Verfügung stellen' means:",opts:["to provide / make available","to take away / withdraw","to put on order / reserve","to apologise / excuse oneself"],a:0,ex:"'die Verfügung' = disposal; to put something at someone's disposal."},{q:"Which Funktionsverbgefüge means 'to consider'?",opts:["in Kraft treten","zur Verfügung stellen","eine Entscheidung treffen","in Betracht ziehen"],a:3,ex:"'in Betracht ziehen' = to consider; the others mean come into force, provide, decide."},{q:"'Während wir verhandelten, ...' becomes:",opts:["Während den Verhandlung ...","Bei der Verhandeln ...","Während der Verhandlungen ...","Während die Verhandlungen ..."],a:2,ex:"'während' as a preposition takes the genitive: während der Verhandlungen."}]},
    {t:"Challenge: professional style",s:"Challenge",qs:[{q:"Which version balances formality and clarity best?",opts:["Wir bitten um Vornahme einer Prüfung des Vertrags bis Freitag.","Prüf mal den Vertrag bis Freitag, ja?","Wir bitten Sie, den Vertrag bis Freitag zu prüfen.","Eine bis Freitag vorzunehmende Vertragsprüfung wird erbeten."],a:2,ex:"It is polite and formal but uses a clear verb instead of a chain of nouns."},{q:"'Nachdem die Verhandlungen gescheitert waren, ...' becomes:",opts:["Nach dem Scheitern den Verhandlungen ...","Nach dem Scheitern der Verhandlungen ...","Nach der Scheiterung der Verhandlungen ...","Nachdem Scheitern der Verhandlungen ..."],a:1,ex:"'scheitern' forms the noun 'das Scheitern' (infinitive); 'nach' + dative, then a genitive."},{q:"Which passive sentence with a Funktionsverbgefüge is correct?",opts:["Die Daten wurden uns zur Verfügung gestellt.","Die Daten wurden uns zur Verfügung gestellen.","Die Daten wurden uns zur Verfügung stellt.","Die Daten haben uns zur Verfügung gestellt worden."],a:0,ex:"The passive is 'werden' + Partizip II: wurden ... gestellt."}]}
  ]
];
